<?php  namespace App\Console\Commands;  use App\Models\Customer; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator;  class ImportCustomersFromCsv extends Command {     protected $signature = 'customers:import-csv {--confirm : Import customers into database}';      protected $description = 'Import customers from cleaned CSV';      public function handle(): int     {         $path = storage_path('app/imports/customers_clean.csv');          if (!is_file($path)) {             $this->error('فایل ورودی پیدا نشد.');             return self::FAILURE;         }          $file = fopen($path, 'r');          if (!$file) {             $this->error('امکان خواندن فایل وجود ندارد.');             return self::FAILURE;         }          $headers = fgetcsv($file);          if (!$headers) {             fclose($file);             $this->error('فایل خالی است.');             return self::FAILURE;         }          $headers[0] = preg_replace('/^\xEF\xBB\xBF/', '', $headers[0]);          $expected = [             'customer_code',             'first_name',             'last_name',             'father_name',             'national_code',             'mobile',         ];          if ($headers !== $expected) {             fclose($file);             $this->error('ساختار ستون‌های فایل صحیح نیست.');             return self::FAILURE;         }          $rows = [];         $line = 1;          while (($values = fgetcsv($file)) !== false) {             $line++;              if (count($values) !== count($headers)) {                 $this->warn("ردیف {$line}: تعداد ستون‌ها نامعتبر است.");                 continue;             }              $row = array_combine($headers, $values);              $validator = Validator::make($row, [                 'customer_code' => ['required', 'integer', 'min:1'],                 'first_name' => ['required', 'string', 'max:50'],                 'last_name' => ['required', 'string', 'max:50'],                 'father_name' => ['nullable', 'string'],                 'national_code' => ['required', 'digits:10'],                 'mobile' => ['required', 'regex:/^09\d{9}$/'],             ]);              if ($validator->fails()) {                 $this->warn("ردیف {$line}: اطلاعات نامعتبر.");                 continue;             }              $rows[] = $row;         }          fclose($file);          $this->info('تعداد ردیف‌های معتبر فایل: ' . count($rows));          if (empty($rows)) {             $this->error('هیچ ردیف معتبری وجود ندارد.');             return self::FAILURE;         }          if (!$this->option('confirm')) {             $this->warn('این فقط پیش‌نمایش است؛ هیچ اطلاعاتی ثبت نشده است.');             return self::SUCCESS;         }          if (!$this->confirm('آیا از ورود اطلاعات به دیتابیس مطمئن هستید؟')) {             $this->warn('عملیات لغو شد.');             return self::SUCCESS;         }          $inserted = 0;         $skipped = 0;          try {             DB::transaction(function () use ($rows, &$inserted, &$skipped) {                 foreach ($rows as $row) {                     $exists = Customer::query()                         ->where('customer_code', $row['customer_code'])                         ->orWhere('national_code', $row['national_code'])                         ->orWhere('mobile', $row['mobile'])                         ->exists();                      if ($exists) {                         $skipped++;                         continue;                     }                      Customer::create([                         'customer_code' => $row['customer_code'],                         'first_name' => $row['first_name'],                         'last_name' => $row['last_name'],                         'father_name' => $row['father_name'] ?: null,                         'national_code' => $row['national_code'],                         'mobile' => $row['mobile'],                     ]);                      $inserted++;                 }             });         } catch (\Throwable $e) {             report($e);             $this->error('خطا در ورود اطلاعات؛ تراکنش بازگردانی شد.');             return self::FAILURE;         }          $this->info("تعداد ثبت‌شده: {$inserted}");         $this->warn("تعداد ردشده به علت تکراری بودن: {$skipped}");          return self::SUCCESS;     } }